import{z as A,x as d,o as t,c as p,q as o,j as n,D as r,d as s,s as l,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"ART 自适应基数树","description":"","frontmatter":{"title":"ART 自适应基数树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/art-adaptive-radix.md","filePath":"cs/art-adaptive-radix.md","lastUpdated":1791063341000}'),B={name:"cs/art-adaptive-radix.md"};function m(T,a,D,u,f,N){const i=d("Mermaid");return t(),p("div",null,[a[2]||(a[2]=o('<h1 id="art-自适应基数树" tabindex="-1">ART 自适应基数树 <a class="header-anchor" href="#art-自适应基数树" aria-label="Permalink to &quot;ART 自适应基数树&quot;">​</a></h1><div class="epigraph"><p>节点类型随扇出变：4、16、48、256；前缀压缩吃掉一元路径。查找沿真实键字节走，不先搅成哈希。</p><footer>—— 据 Leis, Kemper and Neumann, The Adaptive Radix Tree: ARTful Indexing for Main-Memory Databases, ICDE 2013 整理</footer></div><p><a href="/cs/hamt">上一课</a> 用哈希比特，丢失键序。<a href="/cs/trie">Trie</a> 固定 256 数组浪费。<a href="/cs/bplus-split">B+</a> 面向页。<a href="/cs/skip-list">跳表</a> 期望对数比较整键。本课不路径复制整课。缺口是 ART：内存数据库索引，按字节基数、节点形态自适应。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内存中有序索引：比较树 \\(\\log n\\) 次整键比较；哈希表不保序。基数树按字节 \\(O(|key|)\\)，但节点浪费。ART：Node4 存少量键字节+指针；Node16 SIMD 比较；Node48 用 256 字节索引进 48 指针；Node256 直接数组。lazy expansion 与路径压缩合并一元。缺口是<strong>用节点类型匹配实际扇出</strong>，保持字节序（从而范围扫描）。</p><p><span class="marginnote">Leis, Kemper, Neumann, <em>ICDE</em> 2013。整数键可大端字节化以保持序。本课不把论文实验表抄进来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：从根吃前缀，再按下一字节选孩子。插入：节点满则升级类型（4→16→48→256）。删除可降级。范围：有序孩子迭代。并发：乐观锁或 ROWEX 变体，本课点名不写完。</p><p><span class="marginnote">「扇出」就是「一个节点最多能有几个分叉」。可以把它想象成楼道口的指示牌：Node4 只挂 4 块牌子，Node256 把 256 块全挂上；ART 的本事是指示牌数量随人流量自动增减，不必整栋楼统一规格。</span></p>',9)),(t(),n(E,null,{default:r(()=>[l(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E9%94%AE%E5%AD%97%E8%8A%82%22%5D%20--%3E%20N4%5B%22Node4%22%5D%0A%20%20K%20--%3E%20N16%5B%22Node16%22%5D%0A%20%20K%20--%3E%20N48%5B%22Node48%22%5D%0A%20%20K%20--%3E%20N256%5B%22Node256%22%5D%0A%20%20N4%20--%3E%20UP%5B%22%E6%BB%A1%E5%88%99%E5%8D%87%E7%BA%A7%E7%B1%BB%E5%9E%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 HAMT：ART 保序、无哈希；HAMT 持久更容易、无序。与后缀树：ART 是字典不是全部后缀索引。",-1)),a[4]||(a[4]=e("p",null,"字符串课序结束。下一单元概率结构：从通用散列族开始，给后面草图与过滤器提供碰撞合同。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"缓存：小节点密，256 节点吃一页级缓存线若干。前缀压缩使短分支不建多层。键必须能看成字节串；比较器自定义难塞进基数。",-1)),a[7]||(a[7]=e("p",null,"Node48 是四种节点里最巧的一种，它回答的问题是：256 个可能字节怎么只用 48 个槽装下？",-1)),(t(),n(E,null,{default:r(()=>[l(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22%E9%94%AE%E7%9A%84%E4%B8%8B%E4%B8%80%E5%AD%97%E8%8A%82%20%E5%A6%82%200x41%22%5D%20--%3E%20I%5B%22%E6%9F%A5%20256%20%E9%A1%B9%E5%8D%95%E5%AD%97%E8%8A%82%E7%B4%A2%E5%BC%95%22%5D%0A%20%20I%20--%3E%20V%7B%22%E7%B4%A2%E5%BC%95%E5%80%BC%E6%98%AF%E5%90%A6%E5%B0%8F%E4%BA%8E%2048%22%7D%0A%20%20V%20--%3E%7C%22%E6%98%AF%22%7C%20P%5B%22%E6%8C%89%E7%B4%A2%E5%BC%95%E5%8F%96%E5%AF%B9%E5%BA%94%E5%AD%A9%E5%AD%90%E6%8C%87%E9%92%88%22%5D%0A%20%20V%20--%3E%7C%22%E5%90%A6%20%E5%8D%B3%E7%A9%BA%22%7C%20E%5B%22%E8%AF%A5%E5%AD%97%E8%8A%82%E6%B2%A1%E6%9C%89%E5%AD%A9%E5%AD%90%20%E6%9F%A5%E6%89%BE%E5%88%B0%E6%AD%A4%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">数字实例：Node256 给每个字节开一个 8 字节指针要 \\(256\\times 8=2048\\) 字节；Node48 用 256 字节索引加 \\(48\\times 8=384\\) 字节指针，约 640 字节，省了近七成，还保住「按字节直接跳」的 \\(O(1)\\) 一步。</span></p><p>不要把 ART 写成 Transformer 词表；就是内存有序映射。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 ART 与 Bw-tree 对比写长。磁盘仍 B+。哈希族与完美散列是下一课序，不在 ART 里重讲。</p><p><span class="marginnote">常见误区：初学者容易把 ART 想成「一个字符一层」的朴素 Trie，键长 100 就要下 100 层；实际上前缀压缩把没有分叉的公共前缀折成一个前缀项，树深由「分支次数」而不是键长决定，长键也不会把查找拖成线性扫描。</span></p><p>后课默认：内存字节键有序索引可用 ART。碰撞概率的系统合同从通用散列讲起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ART：自适应扇出的字节基数树，保序。</li><li>节点 4/16/48/256 + 前缀压缩。</li><li>字符串结构课序结束；下一课通用散列。</li><li>出处：Leis, Kemper and Neumann, <em>ICDE</em>, 2013。</li></ul>',8))])}const c=A(B,[["render",m]]);export{R as __pageData,c as default};
